    utilities: {
      isObject,

      isFunction,

      isString,

      isFiniteNumber,

      safeString,

      safeNumber,

      safeInteger,

      clampNumber,

      normalizeBoolean,

      normalizeArray,

      uniqueArray,

      createId,

      delay,

      debounce,

      throttle,

      deepClone,

      deepMerge,

      escapeHtml,

      escapeAttribute,

      sanitizeUrl,

      formatFileSize,

      formatCompactNumber,

      formatDate,

      formatRelativeDate,

      getFileExtension,

      detectMediaType,

      normalizeMediaItem,

      normalizeFolder,

      readStorageValue,

      writeStorageValue,

      removeStorageValue,

      normalizeError
    },

    classes: {
      MediaEventBus,

      MediaStateStore,

      MediaLibraryError,

      MediaAuthenticationManager,

      MediaApiClient,

      MediaDomRegistry,

      MediaNotificationManager,

      AiftMediaLibraryCore
    },

    initialize() {
      return application
        .initialize();
    },

    refresh() {
      return application
        .refresh();
    },

    destroy() {
      return application
        .destroy();
    },

    getState() {
      return application.store
        .getState();
    },

