  /* =========================================================
     UPLOAD INTEGRATION
  ========================================================= */

  class ThumbnailUploadIntegration {
    constructor(engine) {
      this.engine = engine;
      this.enabled = true;
      this.bound = false;
      this.unsubscribe = [];
      this.generatedByUploadId = new Map();
    }

    bind() {
      if (this.bound) {
        return this;
      }

      this.bound = true;

      const queue =
        uploads.queue ||
        uploads.uploadQueue ||
        null;

      if (
        queue &&
        typeof queue.use === "function"
      ) {
        const middleware = async (
          context,
          next
        ) => {
          if (!this.enabled) {
            return next();
          }

          const file =
            context.file ||
            (context.item &&
              context.item.file);

          if (!isFile(file)) {
            return next();
          }

          const thumbnailOptions =
            context.thumbnailOptions ||
            (
              context.item &&
              context.item.thumbnailOptions
            ) ||
            {};

          const shouldGenerate =
            thumbnailOptions.enabled !== false &&
            context.generateThumbnail !== false;

          if (!shouldGenerate) {
            return next();
          }

          const result =
            await this.engine.generate(
              file,
              {
                ...thumbnailOptions,
                signal: context.signal,
                output:
                  thumbnailOptions.output ||
                  THUMBNAIL_OUTPUT.BLOB,
                notifyOnFailure: false
              }
            );

          context.thumbnail = result;

          if (context.item) {
            context.item.thumbnail = result;
          }

          const uploadId =
            context.uploadId ||
            (
              context.item &&
              (
                context.item.id ||
                context.item.uploadId
              )
            );

          if (uploadId) {
            this.generatedByUploadId.set(
              String(uploadId),
              result
            );
          }

          return next();
        };

        const unbind =
          queue.use(middleware);

        if (typeof unbind === "function") {
          this.unsubscribe.push(unbind);
        }
      }

      if (
        uploads.manager &&
        typeof uploads.manager.setThumbnailGenerator ===
          "function"
      ) {
        uploads.manager.setThumbnailGenerator(
          async (file, options) =>
            this.engine.generate(
              file,
              options
            )
        );
      }

      emit(
        "media:thumbnail:integration:bound",
        {
          integration: "upload-system"
        }
      );

      return this;
    }

    getByUploadId(uploadId) {
      return (
        this.generatedByUploadId.get(
          String(uploadId)
        ) || null
      );
    }

    releaseByUploadId(uploadId) {
      const key = String(uploadId);
      const result =
        this.generatedByUploadId.get(key);

      if (!result) {
        return false;
      }

      if (
        typeof result.dispose === "function"
      ) {
        result.dispose();
      }

      this.generatedByUploadId.delete(key);

      return true;
    }

    enable() {
      this.enabled = true;
      return this;
    }

    disable() {
      this.enabled = false;
      return this;
    }

    unbind() {
      while (
        this.unsubscribe.length > 0
      ) {
        const unsubscribe =
          this.unsubscribe.pop();

        try {
          unsubscribe();
        } catch (error) {
          console.error(
            "[AIFTMediaLibrary] Thumbnail integration cleanup failed.",
            error
          );
        }
      }

      for (
        const result of
        this.generatedByUploadId.values()
      ) {
        if (
          result &&
          typeof result.dispose === "function"
        ) {
          result.dispose();
        }
      }

      this.generatedByUploadId.clear();
      this.bound = false;

      emit(
        "media:thumbnail:integration:unbound",
        {
          integration: "upload-system"
        }
      );

      return this;
    }
  }

  /* =========================================================
     DOM PREVIEW BINDING
  ========================================================= */

  class ThumbnailPreviewBinder {
    constructor(engine) {
      this.engine = engine;
      this.bindings = new WeakMap();
    }

    async bind(element, file, options) {
      if (
        !element ||
        typeof element !== "object"
      ) {
        throw new TypeError(
          "A valid DOM element is required."
        );
      }

      this.unbind(element);

      const controller =
        new AbortController();

      const result =
        await this.engine.generate(
          file,
          {
            ...(options || {}),
            signal: controller.signal,
            output:
              THUMBNAIL_OUTPUT.OBJECT_URL
          }
        );

      if (
        result.status !==
        THUMBNAIL_STATUS.READY
      ) {
        return result;
      }

      const binding = {
        result,
        controller
      };

      this.bindings.set(
        element,
        binding
      );

      if (
        typeof HTMLImageElement !==
          "undefined" &&
        element instanceof HTMLImageElement
      ) {
        element.src = result.objectUrl;
      } else {
        element.style.backgroundImage =
          `url("${result.objectUrl}")`;
        element.style.backgroundSize =
          options && options.cssFit
            ? options.cssFit
            : "cover";
        element.style.backgroundPosition =
          options &&
          options.cssPosition
            ? options.cssPosition
            : "center";
        element.style.backgroundRepeat =
          "no-repeat";
      }

      element.dataset.aiftThumbnailId =
        result.id;

      return result;
    }

    unbind(element) {
      const binding =
        this.bindings.get(element);

      if (!binding) {
        return false;
      }

      binding.controller.abort(
        createAbortError(
          "Thumbnail preview binding removed."
        )
      );

      if (
        binding.result &&
        typeof binding.result.dispose ===
          "function"
      ) {
        binding.result.dispose();
      }

      if (
        typeof HTMLImageElement !==
          "undefined" &&
        element instanceof HTMLImageElement
      ) {
        element.removeAttribute("src");
      } else if (element.style) {
        element.style.backgroundImage = "";
      }

      if (element.dataset) {
        delete element.dataset.aiftThumbnailId;
      }

      this.bindings.delete(element);

      return true;
    }
  }

