  function resolveAuthorizationToken() {
    const tokenSources = [
      () =>
        global.localStorage &&
        global.localStorage.getItem(
          "token"
        ),

      () =>
        global.localStorage &&
        global.localStorage.getItem(
          "authToken"
        ),

      () =>
        global.localStorage &&
        global.localStorage.getItem(
          "accessToken"
        ),

      () =>
        global.sessionStorage &&
        global.sessionStorage.getItem(
          "token"
        ),

      () =>
        mediaLibrary.auth &&
        typeof mediaLibrary.auth
          .getToken === "function"
          ? mediaLibrary.auth.getToken()
          : null
    ];

    for (const getToken of tokenSources) {
      try {
        const token = getToken();

        if (token) {
          return token;
        }
      } catch (error) {
        console.warn(
          "[AIFT Media Library] Unable to resolve authorization token.",
          error
        );
      }
    }

    return null;
  }

