  function createMediaPreview(options) {
    return new MediaPreviewController(
      options || {}
    );
  }

  async function openMediaPreview(
    asset,
    options
  ) {
    const config =
      options || {};

    let preview =
      config.previewId
        ? previewRegistry.get(
            config.previewId
          )
        : previewRegistry.getDefault();

    if (!preview) {
      preview =
        createMediaPreview(config);
    }

    await preview.open(
      asset,
      config
    );

    return preview;
  }

