  mediaLibrary.mediaPreviewCore =
    mediaPreviewCoreApi;

  mediaLibrary.previewCore =
    mediaPreviewCoreApi;

  mediaLibrary.mediaPreview =
    mediaPreviewCoreApi;

  mediaLibrary.preview =
    mediaPreviewCoreApi;

  mediaLibrary.MediaPreviewController =
    MediaPreviewController;

  mediaLibrary.MediaPreviewApiClient =
    MediaPreviewApiClient;

  mediaLibrary.MediaPreviewState =
    MediaPreviewState;

  mediaLibrary.createMediaPreview =
    createMediaPreview;

  mediaLibrary.openMediaPreview =
    openMediaPreview;

  mediaLibrary.getMediaPreview =
    getMediaPreview;

  mediaLibrary.getDefaultMediaPreview =
    getDefaultMediaPreview;

  mediaLibrary.closeMediaPreview =
    closeMediaPreview;

  mediaLibrary.validateMediaPreviewCore =
    validateMediaPreviewCore;

