  /* =========================================================
     RENDERER REGISTRATION
  ========================================================= */

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.IMAGE,
    MediaPreviewImageRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.VIDEO,
    MediaPreviewVideoRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.AUDIO,
    MediaPreviewAudioRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.PDF,
    MediaPreviewPdfRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.DOCUMENT,
    MediaPreviewDocumentRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.PRESENTATION,
    MediaPreviewPresentationRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.SPREADSHEET,
    MediaPreviewSpreadsheetRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.TEXT,
    MediaPreviewTextRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.CODE,
    MediaPreviewCodeRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.ARCHIVE,
    MediaPreviewArchiveRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.FOLDER,
    MediaPreviewFolderRenderer
  );

  previewCore.rendererRegistry.register(
    MEDIA_PREVIEW_TYPE.UNSUPPORTED,
    MediaPreviewUnsupportedRenderer
  );

  /* =========================================================
     BROWSER OPEN INTEGRATION
  ========================================================= */

  const assetBrowserApi =
    mediaLibrary.assetBrowser ||
    mediaLibrary.mediaAssetBrowser ||
    null;

  if (
    assetBrowserApi &&
    assetBrowserApi.MediaAssetBrowser
  ) {
    const MediaAssetBrowser =
      assetBrowserApi.MediaAssetBrowser;

    const originalOpenAsset =
      MediaAssetBrowser.prototype.openAsset;

    MediaAssetBrowser.prototype.openAsset =
      async function openAssetWithProductionPreview(
        assetId,
        options
      ) {
        const config =
          options || {};

        const asset =
          typeof assetId === "object"
            ? assetId
            : this.getAsset(assetId);

        if (!asset) {
          return originalOpenAsset.call(
            this,
            assetId,
            options
          );
        }

        if (
          asset.isFolder ||
          asset.previewType ===
            MEDIA_PREVIEW_TYPE.FOLDER
        ) {
          return this.openFolder(
            asset.id
          );
        }

        const visibleAssets =
          this.getVisibleAssets()
            .filter(
              (candidate) =>
                !candidate.isFolder
            );

        const normalizedAssets =
          previewCore.utilities
            .normalizePreviewAssets(
              visibleAssets
            );

        const previewAsset =
          previewCore.utilities
            .normalizePreviewAsset(
              asset
            );

        const index =
          normalizedAssets.findIndex(
            (candidate) =>
              String(candidate.id) ===
              String(previewAsset.id)
          );

        try {
          const preview =
            await previewCore.open(
              previewAsset,
              {
                source:
                  "media-browser",
                assets:
                  normalizedAssets,
                index:
                  index >= 0
                    ? index
                    : 0,
                browserId:
                  this.id,
                ...config
              }
            );

          safelyEmit(
            "media:asset-browser:preview-opened",
            {
              browserId:
                this.id,
              asset:
                previewAsset,
              previewId:
                preview.id
            }
          );

          return preview;
        } catch (error) {
          console.error(
            "[AIFT Media Preview] Production preview failed.",
            error
          );

          safelyNotify(
            "error",
            error.message ||
              "The preview could not be opened."
          );

          if (
            config.fallbackToOriginal !==
            false
          ) {
            return originalOpenAsset.call(
              this,
              assetId,
              options
            );
          }

          throw error;
        }
      };
  }

  /* =========================================================
     VALIDATION
  ========================================================= */

  function validatePreviewRenderers() {
    const requiredTypes = [
      MEDIA_PREVIEW_TYPE.IMAGE,
      MEDIA_PREVIEW_TYPE.VIDEO,
      MEDIA_PREVIEW_TYPE.AUDIO,
      MEDIA_PREVIEW_TYPE.PDF,
      MEDIA_PREVIEW_TYPE.DOCUMENT,
      MEDIA_PREVIEW_TYPE.PRESENTATION,
      MEDIA_PREVIEW_TYPE.SPREADSHEET,
      MEDIA_PREVIEW_TYPE.TEXT,
      MEDIA_PREVIEW_TYPE.CODE,
      MEDIA_PREVIEW_TYPE.ARCHIVE,
      MEDIA_PREVIEW_TYPE.FOLDER,
      MEDIA_PREVIEW_TYPE.UNSUPPORTED
    ];

    const checks = {};

    for (const type of requiredTypes) {
      checks[type] =
        previewCore.rendererRegistry.has(
          type
        );
    }

    const missing =
      Object.entries(checks)
        .filter(
          ([, available]) =>
            !available
        )
        .map(([type]) => type);

    return {
      valid:
        missing.length === 0,

      checks,

      missing,

      message:
        missing.length === 0
          ? "Part 2K-C preview renderers are installed correctly."
          : `Missing preview renderers: ${missing.join(
              ", "
            )}`
    };
  }

