  const STYLE_ID =
    "aift-media-preview-annotations-styles";

  /* =========================================================
     UTILITIES
  ========================================================= */

  function safelyEmit(eventName, payload) {
    if (!events) {
      return;
    }

    try {
      if (
        typeof events.emit === "function"
      ) {
        events.emit(
          eventName,
          payload
        );

        return;
      }

      if (
        typeof events.dispatch ===
        "function"
      ) {
        events.dispatch(
          eventName,
          payload
        );

        return;
      }

      if (
        typeof events.publish ===
        "function"
      ) {
        events.publish(
          eventName,
          payload
        );
      }
    } catch (error) {
      console.error(
        `[AIFT Media Preview] Unable to emit "${eventName}".`,
        error
      );
    }
  }

  function safelyNotify(type, message) {
    if (!message) {
      return;
    }

    if (!notifications) {
      if (type === "error") {
        console.error(message);
      }

      return;
    }

    try {
      if (
        typeof notifications[type] ===
        "function"
      ) {
        notifications[type](message);
        return;
      }

      if (
        typeof notifications.show ===
        "function"
      ) {
        notifications.show({
          type,
          message
        });
      }
    } catch (error) {
      console.error(
        "[AIFT Media Preview] Notification failed.",
        error
      );
    }
  }

  function interpolateEndpoint(
    endpoint,
    values
  ) {
    let output =
      String(endpoint || "");

    for (const [key, value] of Object.entries(
      values || {}
    )) {
      output = output.replace(
        new RegExp(`:${key}\\b`, "g"),
        encodeURIComponent(
          String(value)
        )
      );
    }

    return output;
  }

  function normalizeUser(rawUser) {
    if (!rawUser) {
      return null;
    }

    return {
      id:
        normalizeString(
          rawUser.id ||
          rawUser._id ||
          rawUser.userId
        ),

      name:
        normalizeString(
          rawUser.name ||
          rawUser.fullName ||
          rawUser.displayName ||
          rawUser.email
        ),

      email:
        normalizeString(
          rawUser.email
        ),

      role:
        normalizeLowercase(
          rawUser.role
        ) || "default",

      avatarUrl:
        normalizeString(
          rawUser.avatarUrl ||
          rawUser.profileImage ||
          rawUser.photoUrl
        )
    };
  }

  function normalizeReply(rawReply) {
    if (!rawReply) {
      return null;
    }

    return {
      id:
        normalizeString(
          rawReply.id ||
          rawReply._id
        ) ||
        createUniqueId(
          "annotation_reply"
        ),

      text:
        normalizeString(
          rawReply.text ||
          rawReply.body
        ),

      author:
        normalizeUser(
          rawReply.author ||
          rawReply.user ||
          rawReply.createdBy
        ),

      mentions:
        Array.isArray(
          rawReply.mentions
        )
          ? rawReply.mentions
              .map(normalizeUser)
              .filter(Boolean)
          : [],

      createdAt:
        rawReply.createdAt ||
        new Date().toISOString(),

      updatedAt:
        rawReply.updatedAt ||
        rawReply.createdAt ||
        new Date().toISOString()
    };
  }

  function normalizeAnnotation(
    rawAnnotation
  ) {
    if (!rawAnnotation) {
      return null;
    }

    const type =
      Object.values(
        ANNOTATION_TYPE
      ).includes(rawAnnotation.type)
        ? rawAnnotation.type
        : ANNOTATION_TYPE.COMMENT;

    const status =
      Object.values(
        ANNOTATION_STATUS
      ).includes(rawAnnotation.status)
        ? rawAnnotation.status
        : ANNOTATION_STATUS.ACTIVE;

    const position =
      rawAnnotation.position &&
      typeof rawAnnotation.position ===
        "object"
        ? {
            x:
              clampNumber(
                Number(
                  rawAnnotation.position.x
                ) || 0,
                0,
                1
              ),

            y:
              clampNumber(
                Number(
                  rawAnnotation.position.y
                ) || 0,
                0,
                1
              )
          }
        : null;

    const drawing =
      rawAnnotation.drawing &&
      typeof rawAnnotation.drawing ===
        "object"
        ? {
            points:
              Array.isArray(
                rawAnnotation.drawing.points
              )
                ? rawAnnotation.drawing.points
                    .map((point) => ({
                      x:
                        clampNumber(
                          Number(point.x) || 0,
                          0,
                          1
                        ),

                      y:
                        clampNumber(
                          Number(point.y) || 0,
                          0,
                          1
                        )
                    }))
                : [],

            strokeColor:
              normalizeString(
                rawAnnotation.drawing.strokeColor
              ) ||
              ANNOTATION_DEFAULTS.defaultStrokeColor,

            strokeWidth:
              clampNumber(
                Number(
                  rawAnnotation.drawing.strokeWidth
                ) ||
                ANNOTATION_DEFAULTS.defaultStrokeWidth,
                ANNOTATION_DEFAULTS.minimumStrokeWidth,
                ANNOTATION_DEFAULTS.maximumStrokeWidth
              )
          }
        : null;

    return {
      id:
        normalizeString(
          rawAnnotation.id ||
          rawAnnotation._id
        ) ||
        createUniqueId(
          "media_annotation"
        ),

      assetId:
        normalizeString(
          rawAnnotation.assetId ||
          rawAnnotation.mediaId
        ),

      type,

      status,

      text:
        normalizeString(
          rawAnnotation.text ||
          rawAnnotation.body ||
          rawAnnotation.comment
        ),

      position,

      drawing,

      timestamp:
        Number.isFinite(
          Number(
            rawAnnotation.timestamp
          )
        )
          ? Math.max(
              0,
              Number(
                rawAnnotation.timestamp
              )
            )
          : null,

      page:
        Number.isFinite(
          Number(rawAnnotation.page)
        )
          ? Math.max(
              1,
              Number(
                rawAnnotation.page
              )
            )
          : null,

      author:
        normalizeUser(
          rawAnnotation.author ||
          rawAnnotation.user ||
          rawAnnotation.createdBy
        ),

      mentions:
        Array.isArray(
          rawAnnotation.mentions
        )
          ? rawAnnotation.mentions
              .map(normalizeUser)
              .filter(Boolean)
          : [],

      replies:
        Array.isArray(
          rawAnnotation.replies
        )
          ? rawAnnotation.replies
              .map(normalizeReply)
              .filter(Boolean)
          : [],

      metadata:
        rawAnnotation.metadata &&
        typeof rawAnnotation.metadata ===
          "object"
          ? {
              ...rawAnnotation.metadata
            }
          : {},

      createdAt:
        rawAnnotation.createdAt ||
        new Date().toISOString(),

      updatedAt:
        rawAnnotation.updatedAt ||
        rawAnnotation.createdAt ||
        new Date().toISOString()
    };
  }

  function extractMentions(text) {
    const source =
      String(text || "");

    const matches =
      source.match(
        /(^|\s)@([a-zA-Z0-9._-]+)/g
      ) || [];

    return Array.from(
      new Set(
        matches
          .map((match) =>
            match
              .trim()
              .replace(/^@/, "")
          )
          .filter(Boolean)
      )
    );
  }

  function resolveDisplayTime(annotation) {
    if (
      Number.isFinite(
        Number(
          annotation.timestamp
        )
      )
    ) {
      return formatDuration(
        annotation.timestamp
      );
    }

    if (
      Number.isFinite(
        Number(annotation.page)
      )
    ) {
      return `Page ${annotation.page}`;
    }

    return "";
  }

  function getRelativePoint(
    element,
    clientX,
    clientY
  ) {
    const rect =
      element.getBoundingClientRect();

    if (
      rect.width <= 0 ||
      rect.height <= 0
    ) {
      return {
        x: 0,
        y: 0
      };
    }

    return {
      x:
        clampNumber(
          (
            clientX -
            rect.left
          ) /
          rect.width,
          0,
          1
        ),

      y:
        clampNumber(
          (
            clientY -
            rect.top
          ) /
          rect.height,
          0,
          1
        )
    };
  }

