  /* =========================================================
     TARGET TYPE TO ADAPTER MAPPING
  ========================================================= */

  function resolveAdapterTypeForTarget(
    targetType
  ) {
    const mapping = {
      [
        MEDIA_INSERTION_TARGET_TYPE.CLASS_CONTENT
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.BUILDER_CANVAS,

      [
        MEDIA_INSERTION_TARGET_TYPE.LESSON
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.LESSON,

      [
        MEDIA_INSERTION_TARGET_TYPE.MODULE
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.MODULE,

      [
        MEDIA_INSERTION_TARGET_TYPE.PRESENTATION
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.PRESENTATION,

      [
        MEDIA_INSERTION_TARGET_TYPE.PRESENTATION_SLIDE
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.PRESENTATION_SLIDE,

      [
        MEDIA_INSERTION_TARGET_TYPE.QUIZ
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.QUIZ,

      [
        MEDIA_INSERTION_TARGET_TYPE.QUIZ_QUESTION
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.QUIZ_QUESTION,

      [
        MEDIA_INSERTION_TARGET_TYPE.ASSIGNMENT
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.ASSIGNMENT,

      [
        MEDIA_INSERTION_TARGET_TYPE.ANNOUNCEMENT
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.ANNOUNCEMENT,

      [
        MEDIA_INSERTION_TARGET_TYPE.RICH_TEXT
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.RICH_TEXT,

      [
        MEDIA_INSERTION_TARGET_TYPE.GALLERY
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.GALLERY,

      [
        MEDIA_INSERTION_TARGET_TYPE.COURSE_THUMBNAIL
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.THUMBNAIL,

      [
        MEDIA_INSERTION_TARGET_TYPE.CLASS_COVER
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.COVER,

      [
        MEDIA_INSERTION_TARGET_TYPE.BANNER
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.BANNER,

      [
        MEDIA_INSERTION_TARGET_TYPE.PROFILE_IMAGE
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.THUMBNAIL,

      [
        MEDIA_INSERTION_TARGET_TYPE.FILE_ATTACHMENT
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.ATTACHMENT,

      [
        MEDIA_INSERTION_TARGET_TYPE.DOCUMENT
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.RICH_TEXT,

      [
        MEDIA_INSERTION_TARGET_TYPE.MESSAGE
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.RICH_TEXT,

      [
        MEDIA_INSERTION_TARGET_TYPE.POST
      ]:
        MEDIA_INSERTION_ADAPTER_TYPE.RICH_TEXT
    };

    return (
      mapping[targetType] ||
      MEDIA_INSERTION_ADAPTER_TYPE.DOM
    );
  }

  /* =========================================================
     TARGET REGISTRATION HELPERS
  ========================================================= */

  function registerProductionInsertionTarget(
    definition
  ) {
    const config =
      definition || {};

    const targetType =
      config.type ||
      MEDIA_INSERTION_TARGET_TYPE.CUSTOM;

    const adapterType =
      config.adapterType ||
      resolveAdapterTypeForTarget(
        targetType
      );

    const adapter =
      config.adapter ||
      adapterRegistry.create(
        adapterType,
        mergeObjects(
          MEDIA_INSERTION_ADAPTER_DEFAULTS,
          config.adapterOptions ||
          {}
        )
      );

    if (!adapter) {
      throw new MediaInsertionError(
        `No media insertion adapter is registered for "${adapterType}".`,
        {
          code:
            MEDIA_INSERTION_ERROR_CODE.TARGET_UNAVAILABLE
        }
      );
    }

    return insertionCore.registerTarget({
      ...config,

      type:
        targetType,

      metadata: {
        ...(config.metadata || {}),

        adapterType
      },

      insert:
        async (context) => {
          return adapter.insert(
            context
          );
        }
    });
  }

